-- Epic Level Handbook Chapter 1: Epic Skills.
-- Source uses D&D 3.0 skill names in places. D&D 3.5 canonical equivalents are recorded explicitly
-- in mechanics rather than silently rewriting the source terminology.

WITH desired(slug,name,page,kind,rules_text,tags,mechanics) AS (VALUES
  ('elh-epic-skills-general','Epic Skill Checks','38','subsystem',
   'Epic skill checks use the normal d20 + skill modifier procedure. Unless a specific use says otherwise, epic skill uses are extraordinary abilities and continue to function in antimagic. Extremely high DCs are expected for legendary tasks.',
   '["epic","skills","checks","extraordinary"]',
   '{"checkFormula":"1d20 + skill modifier","defaultAbilityType":"extraordinary","functionsInAntimagic":true,"arbitraryHighDcAllowed":true}'),
  ('elh-epic-skill-cooperation','Epic Skill Cooperation','38','variant',
   'Optional rule: a helper grants +2 on a check result of 10-19, +3 on 20-29, +4 on 30-39, and so on. The bonus is floor(helper check / 10) + 1.',
   '["epic","skills","cooperation","variant"]',
   '{"optional":true,"helperMinimumCheck":10,"bonusFormula":"floor(helperCheck / 10) + 1","examples":{"10-19":2,"20-29":3,"30-39":4}}'),
  ('elh-epic-skill-synergy','Epic Skill Synergy','38','rule',
   'A normal +2 synergy bonus gained at 5 ranks increases by an additional +2 for every 20 ranks beyond that threshold: +4 at 25 ranks, +6 at 45 ranks, and so on.',
   '["epic","skills","synergy"]',
   '{"baseRanks":5,"baseBonus":2,"additionalRanksPerIncrease":20,"bonusIncrease":2,"examples":{"25":4,"45":6}}'),

  ('elh-epic-skill-alchemy','Epic Alchemy / Craft (alchemy)','38-39','rule',
   'The source Alchemy skill can identify substances quickly and create more powerful or faster alchemical items. Under D&D 3.5, Alchemy is Craft (alchemy).',
   '["epic","skills","alchemy","craft","3.5-normalization"]',
   '{"sourceSkillName":"Alchemy","canonical35SkillSlug":"craft","specialization":"alchemy","uses":[{"name":"quick identification","dc":50},{"name":"quick creation","dcModifier":"+10 or more, in multiples of 10"},{"name":"augmented substance","dcModifier":"+20 or more"}]}'),
  ('elh-epic-skill-climb','Epic Climb','40','rule',
   'Climb can scale perfectly smooth vertical surfaces and ceilings. Rapid climbing accepts a -20 check penalty; Legendary Climber removes accelerated and rapid climbing penalties.',
   '["epic","skills","climb"]',
   '{"sourceSkillName":"Climb","canonical35SkillSlug":"climb","uses":[{"task":"perfectly smooth flat vertical surface","dc":70},{"task":"perfectly smooth flat overhang or ceiling","dc":100},{"task":"rapid climb at speed as move action or double speed as full-round action","checkModifier":-20}],"legendaryClimberIgnoresAcceleratedAndRapidPenalties":true}'),
  ('elh-epic-skill-concentration','Epic Concentration','40','rule',
   'A caster can attempt to cast a spell with somatic components while grappled with a sufficiently high Concentration check.',
   '["epic","skills","concentration","spellcasting"]',
   '{"sourceSkillName":"Concentration","canonical35SkillSlug":"concentration","uses":[{"task":"cast spell with somatic component while grappled","dcFormula":"50 + spell level"}]}'),
  ('elh-epic-skill-craft','Epic Craft','40','rule',
   'Craft can accelerate item creation by voluntarily increasing the Craft DC in multiples of 10 before making the check.',
   '["epic","skills","craft"]',
   '{"sourceSkillName":"Craft","canonical35SkillSlug":"craft","uses":[{"task":"quick creation","dcModifier":"+10 or more, in multiples of 10","declareBeforeCheck":true}]}'),
  ('elh-epic-skill-decipher-script','Epic Decipher Script','40','rule',
   'Decipher Script can identify a written spell such as a scroll without read magic. Only one attempt per day is allowed.',
   '["epic","skills","decipher-script","scroll"]',
   '{"sourceSkillName":"Decipher Script","canonical35SkillSlug":"decipher-script","uses":[{"task":"decipher written spell without read magic","dcFormula":"50 + 5 * spell level","attemptsPerDay":1}]}'),
  ('elh-epic-skill-diplomacy','Epic Diplomacy: Fanatic Attitude','40-41','rule',
   'Diplomacy can improve an NPC to the fanatic attitude. A fanatic will risk or give life for the character or cause. While fighting for that cause, a fanatic gains +2 morale Strength and Constitution, +1 morale Will, and -1 AC. The attitude lasts 1 day plus 1 day per positive Charisma bonus and is treated as a mind-affecting enchantment effect for immunity, saves, and detection, but is nonmagical and cannot be dispelled.',
   '["epic","skills","diplomacy","fanatic","attitude"]',
   '{"sourceSkillName":"Diplomacy","canonical35SkillSlug":"diplomacy","fanaticDcByInitialAttitude":{"hostile":150,"unfriendly":120,"indifferent":90,"friendly":60,"helpful":50},"fanatic":{"moraleStrength":2,"moraleConstitution":2,"moraleWill":1,"armorClassPenalty":1,"durationFormula":"1 day + 1 day per positive Charisma bonus","mindAffecting":true,"enchantmentEquivalent":true,"magical":false,"dispellable":false,"furtherSkillAttitudeAdjustment":false}}'),
  ('elh-epic-skill-disable-device','Epic Disable Device','40-41','rule',
   'Disable Device can be rushed by increasing the check DC.',
   '["epic","skills","disable-device"]',
   '{"sourceSkillName":"Disable Device","canonical35SkillSlug":"disable-device","uses":[{"time":"1 round","dcModifier":20},{"time":"move-equivalent action","dcModifier":50},{"time":"free action","dcModifier":100}]}'),
  ('elh-epic-skill-disguise','Epic Disguise','41','rule',
   'Disguise can alter apparent height or weight far beyond ordinary disguises, with severe penalties unless a real transformation effect duplicates the change.',
   '["epic","skills","disguise"]',
   '{"sourceSkillName":"Disguise","canonical35SkillSlug":"disguise","uses":[{"heightOrWeightChangePercent":"11-25","checkModifier":-25},{"heightOrWeightChangePercent":"26-50","checkModifier":-50}],"physicalTransformationCanNegatePenalty":true}'),
  ('elh-epic-skill-escape-artist','Epic Escape Artist','41','rule',
   'Escape Artist can squeeze through spaces smaller than the creature''s head and can even find a weakness in a wall of force or similar force effect.',
   '["epic","skills","escape-artist","force"]',
   '{"sourceSkillName":"Escape Artist","canonical35SkillSlug":"escape-artist","uses":[{"task":"extremely tight space","dc":80},{"task":"pass through wall of force or similar force effect","dc":120}]}'),
  ('elh-epic-skill-forgery','Epic Forgery','41','rule',
   'Forgery can create a document without a sample of a similar document or the handwriting being copied; the reader receives a large modifier on the opposed check.',
   '["epic","skills","forgery"]',
   '{"sourceSkillName":"Forgery","canonical35SkillSlug":"forgery","uses":[{"task":"forge document without sample","readerCheckModifier":50}]}'),
  ('elh-epic-skill-gather-information','Epic Gather Information','41','rule',
   'Gather Information can be used without arousing suspicion by accepting a penalty.',
   '["epic","skills","gather-information"]',
   '{"sourceSkillName":"Gather Information","canonical35SkillSlug":"gather-information","uses":[{"task":"avoid suspicion","checkModifier":-20}]}'),
  ('elh-epic-skill-handle-animal','Epic Handle Animal','41','rule',
   'Handle Animal can rear or train magical beasts, vermin, and other unusual creatures and can greatly accelerate training time.',
   '["epic","skills","handle-animal","training"]',
   '{"sourceSkillName":"Handle Animal","canonical35SkillSlug":"handle-animal","uses":[{"task":"rear magical beast","time":"1 year","dcFormula":"30 + HD"},{"task":"train magical beast","time":"2 months","dcFormula":"40 + HD"},{"task":"rear vermin","time":"6 months","dcFormula":"35 + HD"},{"task":"train vermin","time":"2 months","dcFormula":"50 + HD"},{"task":"rear other creature","time":"varies","dcFormula":"40 + HD","dmDiscretion":true},{"task":"train other creature","time":"2 months","dcFormula":"60 + HD","dmDiscretion":true}],"acceleratedTraining":[{"time":"1 month","dcModifier":25},{"time":"1 day","dcModifier":50},{"time":"1 hour","dcModifier":75},{"time":"1 minute","dcModifier":100}],"minimumTrainingTime":"1 minute"}'),
  ('elh-epic-skill-heal','Epic Heal','41-42','rule',
   'Heal can compress a day of long-term care into one hour. The source also lists a DC 100 Perfect Recovery use; its exact effect is retained only where source text is explicit elsewhere rather than inferred here.',
   '["epic","skills","heal","recovery"]',
   '{"sourceSkillName":"Heal","canonical35SkillSlug":"heal","uses":[{"task":"quicken recovery","dc":50,"time":"1 hour","effect":"recover hit points as if receiving a full day of long-term care","maximumPatients":6,"maximumUsesPerPatientPerDay":1},{"task":"perfect recovery","dc":100,"effect":"see source; no unstated details inferred"}]}'),
  ('elh-epic-skill-intimidate','Epic Intimidate','42','rule',
   'Intimidate has no separate epic use, but attempting to intimidate a fanatic has its DC increased by 20.',
   '["epic","skills","intimidate","fanatic"]',
   '{"sourceSkillName":"Intimidate","canonical35SkillSlug":"intimidate","hasDistinctEpicUse":false,"fanaticTargetDcModifier":20}'),
  ('elh-epic-skill-intuit-direction','Epic Intuit Direction / Survival Direction Finding','42','rule',
   'The 3.0 Intuit Direction skill can determine the direction to a location on the same plane based on familiarity. D&D 3.5 removed Intuit Direction; this row preserves the source use and records Survival as the canonical 3.5 skill family rather than silently rewriting the source.',
   '["epic","skills","intuit-direction","survival","3.5-normalization"]',
   '{"sourceSkillName":"Intuit Direction","canonical35SkillSlug":"survival","uses":[{"familiarity":"very familiar","dc":40},{"familiarity":"studied carefully","dc":60},{"familiarity":"seen casually","dc":80},{"familiarity":"viewed once","dc":100},{"familiarity":"description only","dc":120}],"result":"direction only; does not reveal route or obstacles"}'),
  ('elh-epic-skill-jump','Epic Jump','42','rule',
   'Jump has no distinct epic use. A character with Legendary Leaper, and a monk under the source rule, is not restricted by height when determining jump distance.',
   '["epic","skills","jump"]',
   '{"sourceSkillName":"Jump","canonical35SkillSlug":"jump","hasDistinctEpicUse":false,"heightRestrictionRemovedBy":["legendary-leaper","monk source rule"]}'),
  ('elh-epic-skill-knowledge','Epic Knowledge','42','rule',
   'Knowledge has no distinct generic epic use; individual epic subsystems such as epic spellcasting rely on high Knowledge ranks separately.',
   '["epic","skills","knowledge"]',
   '{"sourceSkillName":"Knowledge","hasDistinctEpicUse":false}'),
  ('elh-epic-skill-listen','Epic Listen','42','rule',
   'Listen can automatically recognize an auditory illusion at DC 80 without a Will save, provided its auditory component can be heard. Invisible creatures can be pinpointed by beating the applicable detection DC by 20, though they retain total concealment.',
   '["epic","skills","listen","illusion","invisibility"]',
   '{"sourceSkillName":"Listen","canonical35SkillSlug":"listen","uses":[{"task":"defeat illusion with auditory component","dc":80,"willSaveRequired":false},{"task":"pinpoint invisible creature","dcFormula":"applicable detection DC + 20","targetRetainsTotalConcealment":true}]}'),
  ('elh-epic-skill-move-silently','Epic Move Silently','42','rule',
   'Move Silently has no distinct epic use.',
   '["epic","skills","move-silently"]',
   '{"sourceSkillName":"Move Silently","canonical35SkillSlug":"move-silently","hasDistinctEpicUse":false}'),
  ('elh-epic-skill-open-lock','Epic Open Lock','42','rule',
   'Open Lock can be performed more quickly by increasing the check DC.',
   '["epic","skills","open-lock"]',
   '{"sourceSkillName":"Open Lock","canonical35SkillSlug":"open-lock","uses":[{"time":"move-equivalent action","dcModifier":20},{"time":"free action","dcModifier":50}]}'),
  ('elh-epic-skill-perform','Epic Perform: Fanatic Attitude','42-43','rule',
   'Perform can move an audience to the fanatic attitude. The fanatic state uses the same morale effects and duration model as the epic Diplomacy use.',
   '["epic","skills","perform","fanatic","attitude"]',
   '{"sourceSkillName":"Perform","canonical35SkillSlug":"perform","fanaticDcByInitialAttitude":{"hostile":170,"unfriendly":140,"indifferent":110,"friendly":80,"helpful":70},"usesFanaticStateFrom":"elh-epic-skill-diplomacy"}'),
  ('elh-epic-skill-pick-pocket','Epic Pick Pocket / Sleight of Hand','43','rule',
   'The source presents epic Pick Pocket uses. D&D 3.5 renamed Pick Pocket to Sleight of Hand; this row records that canonical mapping and leaves detailed task DCs to the source-backed use rows as they are imported.',
   '["epic","skills","pick-pocket","sleight-of-hand","3.5-normalization"]',
   '{"sourceSkillName":"Pick Pocket","canonical35SkillSlug":"sleight-of-hand","renamedBy35":true}'),
  ('elh-epic-skill-spot','Epic Spot','43','rule',
   'Spot can detect or pinpoint invisible creatures and automatically defeat visual illusions at DC 80 without a Will save when the visual component can be seen.',
   '["epic","skills","spot","illusion","invisibility"]',
   '{"sourceSkillName":"Spot","canonical35SkillSlug":"spot","uses":[{"task":"notice active invisible creature","dc":20},{"task":"notice unmoving living invisible creature","dc":30},{"task":"notice inanimate invisible object","dc":40},{"task":"notice unmoving unliving invisible creature","dc":40},{"task":"defeat visual illusion","dc":80,"willSaveRequired":false},{"task":"pinpoint invisible creature","dcFormula":"applicable detection DC + 20","targetRetainsTotalConcealment":true}]}'),
  ('elh-epic-skill-swim','Epic Swim','43','rule',
   'Swim can scale a waterfall or other angled or vertical surface while mostly immersed, and can move at greatly increased speed by accepting a penalty.',
   '["epic","skills","swim"]',
   '{"sourceSkillName":"Swim","canonical35SkillSlug":"swim","uses":[{"task":"swim up waterfall or mostly immersed vertical water surface","dc":80},{"task":"speed swimming","checkModifier":-20,"moveActionDistance":"speed","fullRoundDistance":"double speed"}]}'),
  ('elh-epic-skill-tumble','Epic Tumble','43','rule',
   'Tumble can reduce or negate falling damage, stand from prone as a free action, or bounce between nearby vertical surfaces to climb during normal movement.',
   '["epic","skills","tumble","falling"]',
   '{"sourceSkillName":"Tumble","canonical35SkillSlug":"tumble","uses":[{"task":"treat fall as 20 feet shorter","dc":30},{"task":"stand from prone as free action","dc":35},{"task":"treat fall as 30 feet shorter","dc":45},{"task":"climb vertical surface by bouncing up to 20 feet as part of normal movement","dc":50,"requiresTwoVerticalSurfacesWithinFeet":10},{"task":"treat fall as 40 feet shorter","dc":60},{"task":"ignore falling damage","dc":100}]}'),
  ('elh-epic-skill-survival','Epic Wilderness Lore / Survival','43-44','rule',
   'The source Wilderness Lore skill gains several legendary uses. D&D 3.5 renamed and consolidated Wilderness Lore into Survival; this row preserves the source naming while mapping mechanics to the 3.5 skill.',
   '["epic","skills","wilderness-lore","survival","3.5-normalization"]',
   '{"sourceSkillName":"Wilderness Lore","canonical35SkillSlug":"survival","uses":[{"task":"get along in the wild while moving at full speed","dc":40,"extraPeopleFormula":"+1 per 2 points above 40"},{"task":"automatically succeed on Fortitude saves against severe weather","dc":60,"extraPeopleFormula":"+1 per 2 points above 60"},{"task":"ignore terrain penalties to overland movement","dc":60,"extraPeopleFormula":"+1 per 5 points above 60"},{"task":"identify race or kind of creature from tracks","dc":60,"requiresFeat":"Track"}]}')
)
INSERT INTO dnd35_rules
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,
   category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT 'elh-rule-'||d.slug,'elh-3.0',d.page,d.slug,d.name,'',d.rules_text,0,NULL,1,
       'epic-skills',d.kind,CASE WHEN d.kind='variant' THEN 1 ELSE 0 END,CASE WHEN d.kind='variant' THEN 0 ELSE 1 END,
       'elh-epic-skills-general',NULL,d.tags,d.mechanics
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_rules r WHERE r.source_id='elh-3.0' AND r.slug=d.slug AND r.owner_user_id IS NULL
);